import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"ModuleWorker — takoform_module_worker","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/module-worker.md","filePath":"proposals/edge/module-worker.md"}'),i={name:"proposals/edge/module-worker.md"};function n(s,e,d,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="moduleworker-—-takoform-module-worker" tabindex="-1">ModuleWorker — <code>takoform_module_worker</code> <a class="header-anchor" href="#moduleworker-—-takoform-module-worker" aria-label="Permalink to &quot;ModuleWorker — `takoform_module_worker`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An application team runs an HTTP/event application as one ES Module Worker on a proven edge platform. Consumers address the worker by its logical identity: deployments, domains, triggers, consumers, and service bindings all point at this resource, never at a specific build.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The Form carries no desired fields: everything that can change — code, configuration, bindings, traffic — lives on revision and deployment resources around it.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The identity fixes the ES Module Worker ABI, and says exactly what that ABI is: the exact Interface contract <code>worker.runtime@1.1.0</code> (<a href="./../../spec/decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>). That contract fixes the module&#39;s default-export shape and that a declared handler must exist; the <code>fetch</code>, <code>scheduled</code>, and <code>queue</code> signatures and what each event carries; the <code>env</code> object (every declared binding, var, and sensitive-variable slot, and nothing else portable); <code>ctx.waitUntil</code>; exception handling; request and response body streaming; the minimum Web API surface; and which module media types load, which a bundle merely carries without ever importing them, and how a WASM module is instantiated. An instance is stateless between events; durable state lives behind bindings.</p><p>There is no compatibility date and no compatibility flag. A date selects behavior only against a registry that says which behavior each date changes, this project has none, and a Form field that promises portability it cannot deliver is the incompleteness <code>portability-boundary.md</code> forbids. A runtime revision is a new exact contract version — and, if it changes what this Form desires, a new Form version.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Every consumer of the family programs against exactly this ABI. Splitting the identity from the ABI would let two hosts attach the same deployments to observably different runtimes.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A WASI function, an OCI container service, or an isolate model with a different handler contract each preserve a different shape and are separate Forms in other families.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>worker.runtime@1.1.0</code> — the runtime ABI a conforming host provides to this worker&#39;s code. It is held by the IDENTITY because the identity is what a host implements; a Worker Version is the code that fills it.</p><p><code>worker.service@1.0.0</code> — worker-to-worker <code>fetch</code> invocation. It is held by the identity too: a <code>module-worker.service</code> binding addresses another worker by logical identity, and whichever versions that worker&#39;s active deployment selects are what answer.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None. Capability bindings belong to revision resources (decision 0010).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting the identity while versions, deployments, or attachments reference it must fail with <code>dependency_in_use</code>. Delete/recreate mints a new UID (decision 0011); stale references never rebind silently.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The module-worker execution model of a proven edge platform, retained here without its vendor, account, or commercial surface. The retained v1alpha2 <code>EdgeWorker</code> candidate is prior art that this family supersedes for new design work.</p>',21)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
